package com.m3.collections;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.Random;
import org.junit.jupiter.api.Test;

/** Generated by M3LeetCodifyRecipe: original bisection kernels of M3LongTreeSet against M3LaneSearch on generated inputs. */
//FLLDCIM: LEETCODIFY — differential proof for M3LongTreeSet
class M3LongTreeSetLeetCodifyDifferentialTest {
    private static final int SEEDS = 8;
    private static final int MAX_LENGTH = 64;
    private static final int SPAN = 16;

    private static int kernel0(long[] pageMaxima, int low, int high, long value) {
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (value <= pageMaxima[mid]) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static void check0(long[] lane, long key) {
        assertEquals(kernel0(lane, 0, lane.length, key), M3LaneSearch.lowerBound(lane, 0, lane.length, key));
    }

    @Test
    void site0_locatePage() {
        long[] edge = {Long.MIN_VALUE, -1L, 0L, 1L, Long.MAX_VALUE};
        check0(new long[0], 0L);
        check0(new long[] {7L}, 6L);
        check0(new long[] {7L}, 7L);
        check0(new long[] {7L}, 8L);
        check0(new long[] {2L, 2L, 2L, 5L, 5L}, 2L);
        check0(new long[] {2L, 2L, 2L, 5L, 5L}, 3L);
        check0(new long[] {2L, 2L, 2L, 5L, 5L}, 5L);
        for (long key : edge) check0(edge, key);
        for (int seed = 0; seed < SEEDS; seed++) {
            Random random = new Random(seed);
            long[] lane = random.longs(random.nextInt(MAX_LENGTH), -SPAN, SPAN).sorted().toArray();
            for (long key = -SPAN - 1; key <= SPAN + 1; key++) check0(lane, key);
        }
    }
}
